insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público desenvolverá plano específico de medidas, renovado a cada período de 4 anos, para facilitar o acesso a crédito especializado, inclusive linhas subsidiadas para a aquisição de tecnologia assistiva; agilizar, simplificar e priorizar procedimentos de importação; criar mecanismos de fomento à pesquisa e à produção nacional; eliminar ou reduzir a tributação da cadeia produtiva e da importação; e facilitar a inclusão de novos recursos no rol de produtos distribuídos pelo SUS. Os procedimentos serão avaliados, pelo menos, a cada 2 anos.', '["Plano renovado a cada 4 anos.","Crédito, importação, fomento e tributação.","Inclusão de recursos no SUS.","Avaliação a cada 2 anos."]'::jsonb, '["Plano de 4 anos; avaliação a cada 2 anos."]'::jsonb, 'O governo reduz o imposto de importação de próteses.', '["Assertiva que fixa o plano em 10 anos erra: é renovado a cada 4 anos."]'::jsonb, '[]'::jsonb, '["Art. 74"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-75'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público deve garantir à pessoa com deficiência todos os direitos políticos e a oportunidade de exercê-los em igualdade de condições. Assegura-se o direito de votar e de ser votada, inclusive com procedimentos, instalações e equipamentos de votação apropriados e acessíveis, sendo vedada a instalação de seções eleitorais exclusivas para pessoa com deficiência; incentivo à candidatura e ao desempenho de funções públicas; recursos de acessibilidade nos pronunciamentos oficiais, propaganda obrigatória e debates na TV; e livre exercício do voto, com auxílio de pessoa de sua escolha, quando necessário e a seu pedido.', '["Direito de votar e ser votada.","Vedadas seções eleitorais exclusivas.","Recursos de acessibilidade na propaganda e nos debates.","Auxílio de pessoa de sua escolha na votação."]'::jsonb, '["Vedadas seções eleitorais EXCLUSIVAS para pessoas com deficiência."]'::jsonb, 'A pessoa cega vota com auxílio de alguém de sua confiança.', '["Assertiva que permite seções eleitorais exclusivas para pessoas com deficiência erra: é vedado."]'::jsonb, '[]'::jsonb, '["Art. 96"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-76'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público deve fomentar o desenvolvimento científico, a pesquisa, a inovação e a capacitação tecnológicas voltados à melhoria da qualidade de vida e do trabalho da pessoa com deficiência e sua inclusão social. O fomento deve priorizar a geração de conhecimentos para a prevenção e o tratamento de deficiências e o desenvolvimento de tecnologias assistiva e social. A acessibilidade e as tecnologias devem ser fomentadas por cursos de pós-graduação e formação de recursos humanos. Deve-se fomentar a capacitação tecnológica de instituições públicas e privadas, e as medidas são reavaliadas periodicamente.', '["Fomento à pesquisa e inovação.","Prioridade para prevenção, tratamento e tecnologias assistiva e social.","Reavaliação periódica."]'::jsonb, '["Medidas reavaliadas periodicamente."]'::jsonb, 'A universidade recebe fomento para pesquisar tecnologias assistivas.', '["Assertiva que dispensa a reavaliação periódica das medidas de fomento erra."]'::jsonb, '[]'::jsonb, '["Art. 78"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-77'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Devem ser estimulados a pesquisa, o desenvolvimento, a inovação e a difusão de tecnologias voltadas para ampliar o acesso da pessoa com deficiência às tecnologias da informação e comunicação e às tecnologias sociais. Serão estimulados, em especial, o emprego de tecnologias da informação como instrumento de superação de limitações funcionais e barreiras, e a adoção de soluções que ampliem a acessibilidade à computação e aos sítios da internet, em especial aos serviços de governo eletrônico.', '["Estímulo a tecnologias de informação e comunicação acessíveis.","Acessibilidade ao governo eletrônico."]'::jsonb, '["Destaque para o governo eletrônico."]'::jsonb, 'Os serviços digitais do governo são adaptados para leitores de tela.', '["Assertiva que restringe o estímulo às tecnologias físicas, excluindo as de informação, erra."]'::jsonb, '[]'::jsonb, '["Art. 77"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-78'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público deve assegurar o acesso da pessoa com deficiência à justiça, em igualdade de oportunidades, garantindo, sempre que requeridos, adaptações e recursos de tecnologia assistiva. Deve capacitar membros e servidores do Judiciário, Ministério Público, Defensoria Pública, órgãos de segurança pública e sistema penitenciário quanto aos direitos da pessoa com deficiência. À pessoa submetida a medida restritiva de liberdade devem ser assegurados todos os direitos e garantias dos apenados sem deficiência, garantida a acessibilidade. A Defensoria Pública e o Ministério Público tomarão as medidas necessárias à garantia dos direitos previstos na Lei.', '["Acesso à justiça com adaptações.","Capacitação dos operadores do sistema de justiça.","Direitos do preso com deficiência.","Atuação da Defensoria e do MP."]'::jsonb, '["Capacitação inclui o sistema penitenciário e a segurança pública."]'::jsonb, 'O tribunal oferece intérprete de Libras e a Defensoria atua na defesa dos direitos.', '["Assertiva que isenta o sistema penitenciário da capacitação erra."]'::jsonb, '[]'::jsonb, '["Art. 80"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-79'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Devem ser oferecidos todos os recursos de tecnologia assistiva disponíveis para que a pessoa com deficiência tenha garantido o acesso à justiça, sempre que figure em um dos polos da ação ou atue como testemunha, partícipe da lide, advogado, defensor público, magistrado ou membro do Ministério Público. A pessoa com deficiência tem garantido o acesso ao conteúdo de todos os atos processuais de seu interesse, inclusive no exercício da advocacia.', '["Tecnologia assistiva para qualquer participante do processo.","Acesso ao conteúdo dos atos processuais."]'::jsonb, '["Vale para partes, testemunhas, advogados e membros do Judiciário."]'::jsonb, 'O advogado cego acessa o processo por meio de leitor de tela.', '["Assertiva que restringe os recursos de tecnologia assistiva às partes erra: abrange advogados e magistrados."]'::jsonb, '[]'::jsonb, '["Art. 79"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-80'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os direitos da pessoa com deficiência serão garantidos por ocasião da aplicação de sanções penais.', '["Direitos da pessoa com deficiência na aplicação de sanções penais."]'::jsonb, '["Cumprimento de pena com acessibilidade."]'::jsonb, 'O presídio garante acessibilidade ao preso com deficiência.', '["Assertiva que afasta os direitos da pessoa com deficiência durante a pena erra."]'::jsonb, '[]'::jsonb, '["Art. 79"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-81'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os serviços notariais e de registro não podem negar ou criar óbices ou condições diferenciadas à prestação de seus serviços em razão de deficiência do solicitante, devendo reconhecer sua capacidade legal plena, garantida a acessibilidade. O descumprimento constitui discriminação em razão de deficiência.', '["Cartórios não podem negar serviços por causa da deficiência.","Capacidade legal plena.","Descumprimento é discriminação."]'::jsonb, '["Cartórios reconhecem a capacidade plena."]'::jsonb, 'O cartório não pode se recusar a lavrar escritura de pessoa com deficiência.', '["Assertiva que permite ao cartório exigir curador de qualquer pessoa com deficiência erra."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-83'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa com deficiência tem assegurado o direito ao exercício de sua capacidade legal em igualdade de condições. Quando necessário, será submetida à curatela, conforme a lei. É facultado adotar o processo de tomada de decisão apoiada. A curatela é medida protetiva extraordinária, proporcional às necessidades e circunstâncias, e durará o menor tempo possível. Os curadores prestam contas anualmente ao juiz, apresentando o balanço do respectivo ano.', '["Capacidade legal em igualdade de condições.","Curatela como medida extraordinária.","Tomada de decisão apoiada facultativa.","Prestação anual de contas pelo curador."]'::jsonb, '["Curatela é EXTRAORDINÁRIA, proporcional e pelo menor tempo possível.","Contas ANUAIS."]'::jsonb, 'O curador apresenta anualmente o balanço da administração ao juiz.', '["Assertiva que torna a curatela a regra para pessoas com deficiência intelectual erra: ela é extraordinária."]'::jsonb, '[{"termo":"Curatela","significado":"Encargo de administrar bens e atos patrimoniais de pessoa curatelada."}]'::jsonb, '["Art. 85"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-84'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A curatela afetará tão somente os atos relacionados aos direitos de natureza patrimonial e negocial. A definição da curatela não alcança o direito ao próprio corpo, à sexualidade, ao matrimônio, à privacidade, à educação, à saúde, ao trabalho e ao voto. Constitui medida extraordinária, devendo constar da sentença as razões e motivações de sua definição, preservados os interesses do curatelado. Em situação de institucionalização, o juiz deve dar preferência a curador com vínculo familiar, afetivo ou comunitário.', '["Curatela só afeta atos patrimoniais e negociais.","Não alcança corpo, sexualidade, casamento, privacidade, educação, saúde, trabalho e voto.","Sentença motivada.","Preferência por curador com vínculo."]'::jsonb, '["A curatela NÃO retira o direito de votar, casar ou decidir sobre o próprio corpo."]'::jsonb, 'A pessoa curatelada continua podendo votar e se casar.', '["Assertiva que retira da pessoa curatelada o direito ao voto erra."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-85'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para emissão de documentos oficiais, não será exigida a situação de curatela da pessoa com deficiência.', '["Curatela não é exigida para emitir documentos oficiais."]'::jsonb, '["Vedada a exigência de curatela para documentos."]'::jsonb, 'A pessoa com deficiência tira o RG sem precisar de curatela.', '["Assertiva que exige curatela para a emissão de documentos oficiais erra."]'::jsonb, '[]'::jsonb, '["Art. 83"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-86'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em casos de relevância e urgência e a fim de proteger os interesses da pessoa com deficiência em situação de curatela, será lícito ao juiz, ouvido o Ministério Público, de ofício ou a requerimento do interessado, nomear, desde logo, curador provisório, sujeito, no que couber, às disposições do Código de Processo Civil.', '["Curador provisório em casos de relevância e urgência.","Ouvido o Ministério Público."]'::jsonb, '["Nomeação de ofício ou a requerimento, ouvido o MP."]'::jsonb, 'O juiz nomeia curador provisório para proteger o patrimônio em risco.', '["Assertiva que dispensa a oitiva do Ministério Público na nomeação de curador provisório erra."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-87'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Praticar, induzir ou incitar discriminação de pessoa em razão de sua deficiência: reclusão de 1 a 3 anos e multa. Aumenta-se a pena em 1/3 se a vítima estiver sob cuidado e responsabilidade do agente. Se cometido por meios de comunicação social ou de publicação de qualquer natureza, reclusão de 2 a 5 anos e multa. Nesse caso, o juiz poderá determinar, ouvido o Ministério Público e antes do inquérito policial, sob pena de desobediência, o recolhimento ou busca e apreensão do material e a interdição de mensagens ou páginas na internet. É efeito da condenação, após o trânsito em julgado, a destruição do material apreendido.', '["Praticar, induzir ou incitar discriminação: reclusão de 1 a 3 anos e multa.","Aumento de 1/3 se a vítima está sob cuidado do agente.","Meios de comunicação: reclusão de 2 a 5 anos.","Busca e apreensão e interdição de páginas, até antes do inquérito."]'::jsonb, '["Meios de comunicação social: reclusão de 2 a 5 anos."]'::jsonb, 'Publicar na internet conteúdo discriminatório contra pessoas com deficiência agrava a pena.', '["Assertiva que prevê detenção para o crime de discriminação erra: é reclusão."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-88'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apropriar-se de ou desviar bens, proventos, pensão, benefícios, remuneração ou qualquer outro rendimento de pessoa com deficiência: reclusão de 1 a 4 anos e multa. Aumenta-se a pena em 1/3 se o crime é cometido por tutor, curador, síndico, liquidatário, inventariante, testamenteiro ou depositário judicial, ou por aquele que se apropriou em razão de ofício ou de profissão.', '["Apropriação ou desvio de rendimentos da pessoa com deficiência.","Reclusão de 1 a 4 anos e multa.","Aumento de 1/3 para tutor, curador e quem age em razão de ofício."]'::jsonb, '["Aumento de 1/3 se o autor é curador ou tutor."]'::jsonb, 'O curador que desvia a pensão do curatelado responde com pena aumentada de 1/3.', '["Assertiva que prevê detenção para esse crime erra: é reclusão."]'::jsonb, '[]'::jsonb, '["Art. 91"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-89'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Abandonar pessoa com deficiência em hospitais, casas de saúde, entidades de abrigamento ou congêneres: reclusão de 2 a 5 anos e multa. Se do abandono resulta lesão corporal de natureza grave, reclusão de 3 a 7 anos e multa. Se resulta morte, reclusão de 8 a 14 anos e multa. Nas mesmas penas incorre quem não prover as necessidades básicas de pessoa com deficiência quando obrigado por lei ou mandado.', '["Abandono em hospitais ou entidades: reclusão de 2 a 5 anos e multa.","Lesão grave: 3 a 7 anos.","Morte: 8 a 14 anos.","Não prover necessidades básicas."]'::jsonb, '["Qualificadoras: lesão grave (3 a 7 anos) e morte (8 a 14 anos)."]'::jsonb, 'Deixar a pessoa com deficiência em um hospital e desaparecer é abandono.', '["Assertiva que prevê detenção para o abandono erra: é reclusão."]'::jsonb, '[]'::jsonb, '["Art. 89"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-90'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Reter ou utilizar cartão magnético, qualquer meio eletrônico ou documento de pessoa com deficiência destinados ao recebimento de benefícios, proventos, pensões ou remuneração, ou à realização de operações financeiras, com o fim de obter vantagem indevida para si ou para outrem: detenção de 6 meses a 2 anos e multa. Aumenta-se a pena em 1/3 se o crime é cometido por tutor ou curador.', '["Reter ou usar cartão ou documento para obter vantagem indevida.","Detenção de 6 meses a 2 anos e multa.","Aumento de 1/3 se o autor é tutor ou curador."]'::jsonb, '["Pena de DETENÇÃO."]'::jsonb, 'Quem retém o cartão da aposentadoria da pessoa com deficiência para se apropriar do dinheiro comete o crime.', '["Assertiva que prevê reclusão para esse crime erra: é detenção."]'::jsonb, '[]'::jsonb, '["Art. 89"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-91'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É criado o Cadastro Nacional de Inclusão da Pessoa com Deficiência (Cadastro-Inclusão), registro público eletrônico para coletar, processar, sistematizar e disseminar informações georreferenciadas que permitam a identificação e a caracterização socioeconômica da pessoa com deficiência e das barreiras que impedem a realização de seus direitos. É administrado pelo Poder Executivo federal e constituído por base de dados, instrumentos e sistemas eletrônicos, com dados obtidos pela integração dos sistemas de todas as políticas públicas e por censos e pesquisas. É facultada a celebração de convênios com instituições públicas e privadas.', '["Cadastro-Inclusão: registro público eletrônico.","Informações georreferenciadas e socioeconômicas.","Administrado pelo Executivo federal.","Integração de bases e convênios."]'::jsonb, '["Administração pelo Poder Executivo FEDERAL."]'::jsonb, 'O Cadastro-Inclusão reúne dados sobre pessoas com deficiência e barreiras.', '["Assertiva que atribui a administração do Cadastro-Inclusão aos Estados erra: é do Executivo federal."]'::jsonb, '[]'::jsonb, '["Art. 93"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-92'
