insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A antiga Lei de Licitações (Lei nº 8.666, de 21 de junho de 1993) passa a prever preferência para bens e serviços produzidos ou prestados por empresas que comprovem o cumprimento da reserva de cargos para pessoas com deficiência ou reabilitados e que atendam às regras de acessibilidade. Essas empresas deverão cumprir a reserva e as regras de acessibilidade durante todo o período de execução do contrato, e a administração fiscalizará os requisitos de acessibilidade nos serviços e ambientes de trabalho.', '["Preferência a empresas que cumprem a reserva de cargos e a acessibilidade.","Cumprimento durante toda a execução do contrato.","Fiscalização da administração."]'::jsonb, '["ATUALIZAÇÃO: a Lei nº 8.666 foi substituída pela nova Lei de Licitações; confira o regime vigente."]'::jsonb, 'A administração prefere a empresa que cumpre a cota de pessoas com deficiência.', '["Assertiva que dispensa o cumprimento da cota durante a execução do contrato erra."]'::jsonb, '[]'::jsonb, '["Lei de Licitações"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-104'
