insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 20 da Lei Orgânica da Assistência Social (Lei nº 8.742, de 7 de dezembro de 1993) passa a vigorar com alterações: para a concessão do BPC, considera-se pessoa com deficiência aquela que tem impedimento de longo prazo de natureza física, mental, intelectual ou sensorial, o qual, em interação com barreiras, pode obstruir sua participação plena na sociedade; os rendimentos de estágio supervisionado e de aprendizagem não são computados na renda familiar per capita; e poderão ser utilizados outros elementos probatórios da miserabilidade e vulnerabilidade do grupo familiar.', '["Conceito de pessoa com deficiência para o BPC.","Estágio e aprendizagem não entram na renda per capita.","Outros elementos probatórios da miserabilidade."]'::jsonb, '["ATUALIZAÇÃO: altera a LOAS (Lei nº 8.742, de 1993).","Rendimentos de ESTÁGIO e APRENDIZAGEM não contam na renda per capita."]'::jsonb, 'O salário de aprendiz de um filho não é contado no cálculo da renda do BPC.', '["Assertiva que computa o rendimento de aprendizagem na renda per capita do BPC erra."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-105'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei nº 9.029, de 13 de abril de 1995, passa a vigorar com alterações: é proibida a adoção de qualquer prática discriminatória e limitativa para efeito de acesso à relação de trabalho ou de sua manutenção, por motivo de sexo, origem, raça, cor, estado civil, situação familiar, deficiência, reabilitação profissional, idade, entre outros; as infrações são passíveis de cominações, inclusive a reintegração com ressarcimento integral de todo o período de afastamento, mediante pagamento das remunerações devidas, corrigidas monetariamente e acrescidas de juros legais.', '["Proibida a discriminação no acesso e na manutenção do emprego, inclusive por deficiência.","Reintegração com ressarcimento integral."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei nº 9.029, de 1995.","Reintegração com ressarcimento integral."]'::jsonb, 'O empregado dispensado por discriminação é reintegrado e recebe os salários do período.', '["Assertiva que impede a reintegração do empregado dispensado por deficiência erra."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
