insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Código de Trânsito Brasileiro passa a vigorar com alterações: são consideradas vias terrestres as praias abertas à circulação pública, as vias internas de condomínios constituídos por unidades autônomas e as vias e áreas de estacionamento de estabelecimentos privados de uso coletivo; as vagas de estacionamento regulamentado devem ser sinalizadas com placas indicativas de destinação e informando os dados sobre a infração por estacionamento indevido; e ao candidato com deficiência auditiva é assegurada acessibilidade de comunicação em todas as etapas do processo de habilitação, com material didático audiovisual acessível e serviços de intérprete de Libras.', '["Ampliação do conceito de via terrestre.","Placas nas vagas reservadas.","Acessibilidade ao candidato com deficiência auditiva na habilitação."]'::jsonb, '["ATUALIZAÇÃO: altera o Código de Trânsito Brasileiro (arts. 2º, 86-A e 147-A)."]'::jsonb, 'O candidato surdo a habilitação pode requerer intérprete de Libras.', '["Assertiva que não prevê acessibilidade ao candidato com deficiência auditiva no processo de habilitação erra."]'::jsonb, '[]'::jsonb, '["Código de Trânsito Brasileiro"]'::jsonb, 'under_review', 'claude'
