select u.id, u.content_sha256, 'A Lei nº 10.098, de 19 de dezembro de 2000 (Lei da Acessibilidade), passa a vigorar com alterações nas definições, entre elas a de acessibilidade (possibilidade e condição de alcance, com segurança e autonomia, de espaços, mobiliários, edificações, transportes, informação e comunicação) e a de barreiras, classificadas em urbanísticas, arquitetônicas, nos transportes, nas comunicações e na informação, entre outras.', '["Atualiza as definições de acessibilidade e barreiras.","Classificação das barreiras."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei nº 10.098, de 2000."]'::jsonb, 'As barreiras nos transportes e nas comunicações são categorias definidas pela lei.', '["Assertiva que restringe as barreiras às arquitetônicas erra: há outras categorias."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
