insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Código Civil passa a vigorar com alterações: são absolutamente incapazes apenas os menores de 16 anos; são relativamente incapazes, entre outros, os ébrios habituais, os viciados em tóxico e aqueles que, por causa transitória ou permanente, não puderem exprimir sua vontade; a pessoa com deficiência poderá testemunhar em igualdade de condições, com recursos de tecnologia assistiva; os pais ou tutores podem revogar a autorização até a celebração do casamento; e a pessoa com deficiência mental ou intelectual em idade núbil poderá contrair matrimônio, expressando sua vontade diretamente ou por meio de seu responsável ou curador.', '["Absolutamente incapazes: só os menores de 16 anos.","Pessoa com deficiência pode testemunhar.","Pessoa com deficiência pode casar."]'::jsonb, '["ATUALIZAÇÃO: altera o Código Civil (arts. 3º, 4º, 228, 1.518, 1.548, 1.550, 1.557).","A deficiência NÃO gera mais incapacidade absoluta."]'::jsonb, 'A pessoa com deficiência intelectual pode se casar.', '["Assertiva que mantém a pessoa com deficiência mental como absolutamente incapaz erra: só os menores de 16 anos são absolutamente incapazes."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
