insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Código Civil passa a ter o Capítulo III, da Tomada de Decisão Apoiada. Ela é o processo pelo qual a pessoa com deficiência elege pelo menos 2 pessoas idôneas, com as quais mantenha vínculos e que gozem de sua confiança, para prestar-lhe apoio na tomada de decisão sobre atos da vida civil, fornecendo-lhes os elementos e informações necessários. Para o pedido, a pessoa e os apoiadores apresentam termo com os limites do apoio e os compromissos, inclusive o prazo de vigência. O pedido é requerido pela pessoa apoiada, com indicação dos apoiadores. Antes de decidir, o juiz, assistido por equipe multidisciplinar e ouvido o Ministério Público, ouve pessoalmente o requerente e os apoiadores.', '["Tomada de decisão apoiada.","Pelo menos 2 apoiadores idôneos.","Termo com limites do apoio e prazo de vigência.","Pedido pela própria pessoa apoiada.","Juiz ouve pessoalmente os envolvidos, com equipe multidisciplinar e MP."]'::jsonb, '["Mínimo de 2 apoiadores.","O pedido é da PRÓPRIA pessoa apoiada, e ela mantém sua capacidade."]'::jsonb, 'A pessoa escolhe dois amigos de confiança para apoiá-la nos contratos que fizer.', '["Assertiva que permite a tomada de decisão apoiada com um único apoiador erra: são pelo menos 2."]'::jsonb, '[{"termo":"Tomada de decisão apoiada","significado":"Apoio escolhido pela pessoa com deficiência para decidir, sem perder a capacidade."}]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
