select u.id, u.content_sha256, 'Regulamento disporá sobre a adequação do disposto na Lei ao tratamento diferenciado, simplificado e favorecido a ser dispensado às microempresas e às empresas de pequeno porte, previsto no §3º do art. 1º da Lei Complementar nº 123, de 14 de dezembro de 2006.', '["Adequação às microempresas e empresas de pequeno porte por regulamento."]'::jsonb, '["Tratamento favorecido às ME e EPP."]'::jsonb, 'Uma microempresa pode ter prazos adaptados para cumprir as regras.', '["Assertiva que isenta as microempresas de qualquer obrigação de acessibilidade erra: o regulamento só adequa."]'::jsonb, '[]'::jsonb, '["Art. 125"]'::jsonb, 'under_review', 'claude'
