insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A jurisdição penal dos juízes ou tribunais da justiça ordinária, em todo o território nacional, será exercida, no processo de execução, na conformidade da Lei de Execução Penal e do Código de Processo Penal. A Lei aplica-se igualmente ao preso provisório e ao condenado pela Justiça Eleitoral ou Militar, quando recolhido a estabelecimento sujeito à jurisdição ordinária.', '["Jurisdição da justiça ordinária.","Aplica-se ao preso provisório.","Aplica-se ao condenado pela Justiça Eleitoral ou Militar recolhido em estabelecimento comum."]'::jsonb, '["A LEP também alcança o PRESO PROVISÓRIO."]'::jsonb, 'O preso provisório tem os direitos da LEP, no que couber.', '["Assertiva que afasta a LEP do preso provisório erra: ela se aplica igualmente."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
